import { Dom } from "../../../core/dom/dom.js";
import { $$, attr, isFunction } from "../../../core/helpers/index.js";
import { UIBlock, UIButton, UIForm, UIInput } from "../../../core/ui/index.js";
import { TabsWidget } from "../tabs/tabs.js";
/**
 * Generate 3 tabs
 * upload - Use Drag and Drop
 * url - By specifying the image url
 * filebrowser - After opening the file browser. In the absence of one of the parameters will be less tabs
 *
 * @param callbacks - Object with keys `url`, `upload` and `filebrowser`, values which are callback
 * functions with different parameters
 */
export const FileSelectorWidget = (editor, callbacks, elm, close, isImage = true) => {
    let currentImage;
    const tabs = [];
    const options = editor.o.uploader;
    if (callbacks.upload &&
        options.showTabInFileSelector !== false &&
        (options.url ||
            options.insertImageAsBase64URI ||
            options.customUploadFunction)) {
        const { upload } = callbacks;
        tabs.push(UploadTab(editor, resp => {
            const handler = isFunction(upload)
                ? upload
                : options.defaultHandlerSuccess;
            if (isFunction(handler)) {
                handler.call(editor, resp);
            }
        }, isImage
            ? { label: 'Drop image', accept: 'image/*' }
            : { label: 'Drop file', accept: '*' }));
    }
    if (callbacks.filebrowser) {
        if (editor.o.filebrowser.ajax.url || editor.o.filebrowser.items.url) {
            tabs.push({
                icon: 'folder',
                name: 'Browse',
                content: () => {
                    close && close();
                    if (callbacks.filebrowser) {
                        editor.filebrowser.open(callbacks.filebrowser, isImage);
                    }
                }
            });
        }
    }
    if (callbacks.url) {
        const button = new UIButton(editor, {
            type: 'submit',
            variant: 'primary',
            text: 'Insert'
        });
        const form = new UIForm(editor, [
            new UIInput(editor, {
                required: true,
                label: 'URL',
                name: 'url',
                type: 'text',
                placeholder: 'https://'
            }),
            new UIInput(editor, {
                name: 'text',
                label: 'Alternative text'
            }),
            new UIBlock(editor, [button])
        ]);
        if (elm &&
            !Dom.isText(elm) &&
            !Dom.isComment(elm) &&
            (Dom.isTag(elm, 'img') || $$('img', elm).length)) {
            currentImage = elm.tagName === 'IMG' ? elm : $$('img', elm)[0];
            val(form.container, 'url', attr(currentImage, 'src'));
            val(form.container, 'text', attr(currentImage, 'alt'));
            button.state.text = 'Update';
        }
        if (elm && Dom.isTag(elm, 'a')) {
            val(form.container, 'url', attr(elm, 'href'));
            val(form.container, 'text', attr(elm, 'title'));
            button.state.text = 'Update';
        }
        form.onSubmit(data => {
            if (isFunction(callbacks.url)) {
                callbacks.url.call(editor, data.url, data.text);
            }
        });
        tabs.push({
            icon: 'link',
            name: 'URL',
            content: form.container
        });
    }
    const box = TabsWidget(editor, tabs);
    // Marks this popup so its tabs auto-size to their labels (see
    // `.jodit-file-selector` in tabs.less) — long localized tab captions are no
    // longer clipped — while leaving other tab popups (link …) untouched. The
    // video popup, which has an Upload tab too, uses it as well.
    box.classList.add('jodit-file-selector');
    return box;
};
/**
 * The Upload tab: a box that uploads the files dropped on it or chosen in its
 * file input, then passes the uploader's answer to `onSuccess` and closes the popup
 */
export const UploadTab = (editor, onSuccess, { label, accept }) => {
    const dragBox = editor.c.fromHTML('<div class="jodit-drag-and-drop__file-box">' +
        `<strong>${editor.i18n(label)}</strong>` +
        `<span><br>${editor.i18n('or click')}</span>` +
        `<input type="file" accept="${accept}" tabindex="-1" dir="auto" multiple=""/>` +
        '</div>');
    editor.uploader.bind(dragBox, resp => {
        onSuccess.call(editor, resp);
        editor.e.fire('closeAllPopups');
    }, error => {
        editor.message.error(error.message);
        editor.e.fire('closeAllPopups');
    });
    return {
        icon: 'upload',
        name: 'Upload',
        content: dragBox
    };
};
function val(elm, name, value) {
    const child = Dom.first(elm, node => Dom.isTag(node, 'input') && attr(node, 'name') === name);
    if (!child) {
        return '';
    }
    if (value) {
        child.value = value;
    }
    return child.value;
}
