import { Dom } from "../../../core/dom/index.js";
import { attr, hasBrowserColorPicker, isArray, isFunction, isPlainObject, normalizeColor, refs } from "../../../core/helpers/index.js";
import { Icon } from "../../../core/ui/index.js";
import paletteIcon from "./palette.svg.js";
Icon.set('palette', paletteIcon);
/**
 * Build color picker
 *
 * @param callback - Callback 'function (color) \{\}'. The remove button calls it with an empty string
 * @param coldColor - Color value ex. #fff or rgb(123, 123, 123) or rgba(123, 123, 123, 1)
 * @example
 * ```javascript
 * const tabs = TabsWidget(editor, {
 *    'Text': ColorPickerWidget(editor, function (color) {
 *         box.style.color = color;
 *     }, box.style.color),
 *     'Background': ColorPickerWidget(editor, function (color) {
 *         box.style.backgroundColor = color;
 *     }, box.style.backgroundColor),
 * });
 * ```
 */
export const ColorPickerWidget = (editor, callback, coldColor) => {
    const cn = 'jodit-color-picker', valueHex = normalizeColor(coldColor), form = editor.c.div(cn), iconPalette = editor.o.textIcons
        ? `<span>${editor.i18n('palette')}</span>`
        : Icon.get('palette'), eachColor = (colors) => {
        const stack = [];
        if (isPlainObject(colors)) {
            Object.keys(colors).forEach(key => {
                stack.push(`<div class="${cn}__group ${cn}__group-${key}">`);
                stack.push(eachColor(colors[key]));
                stack.push('</div>');
            });
        }
        else if (isArray(colors)) {
            colors.forEach(color => {
                stack.push(`<span class='${cn}__color-item ${valueHex === color
                    ? cn + '__color-item_active_true'
                    : ''}' title="${color}" style="background-color:${color}" data-color="${color}"></span>`);
            });
        }
        return stack.join('');
    };
    // The group wrapper lays the colors out in rows, so a flat list needs one
    // too. See #1487
    const groups = isArray(editor.o.colors)
        ? `<div class="${cn}__group">${eachColor(editor.o.colors)}</div>`
        : eachColor(editor.o.colors);
    Dom.append(form, editor.c.fromHTML(`<div class="${cn}__groups">${groups}</div>`));
    Dom.append(form, editor.c.fromHTML(`<div data-ref="extra" class="${cn}__extra"></div>`));
    const { extra } = refs(form);
    Dom.append(extra, editor.c.fromHTML(`<div class="${cn}__hex"><input data-ref="hexInput" type="text" spellcheck="false" aria-label="HEX" placeholder="#FF0000" value="${valueHex || ''}"/></div>`));
    const { hexInput } = refs(form);
    // Enter applies the value and closes the popup; removing the focused
    // input then makes Chrome fire `change` on it, which would apply the
    // same color a second time and toggle it off again. See #1459
    let appliedHexValue = null;
    const applyHexInput = () => {
        const raw = hexInput.value.trim();
        if (raw === appliedHexValue) {
            return;
        }
        const isHex = /^#?[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(raw);
        const isRgb = /^rgba?\([\d\s.,%]+\)$/i.test(raw);
        if (!isHex && !isRgb) {
            return;
        }
        const color = normalizeColor(isHex && !raw.startsWith('#') ? '#' + raw : raw);
        if (color && isFunction(callback)) {
            appliedHexValue = raw;
            callback(color);
        }
    };
    editor.e
        .on(hexInput, 'keydown', (e) => {
        e.stopPropagation();
        if (e.key === 'Enter') {
            e.preventDefault();
            applyHexInput();
        }
    })
        .on(hexInput, 'change', (e) => {
        e.stopPropagation();
        applyHexInput();
    });
    Dom.append(extra, editor.c.fromHTML(`<span class="${cn}__remove" data-color="" title="${editor.i18n('Remove')}">${editor.o.textIcons ? editor.i18n('Remove') : Icon.get('eraser')}</span>`));
    if (editor.o.showBrowserColorPicker && hasBrowserColorPicker()) {
        Dom.append(extra, editor.c.fromHTML(`<div class="${cn}__native">${iconPalette}<input type="color" value="#ffffff"/></div>`));
        editor.e.on(form, 'change', (e) => {
            e.stopPropagation();
            const target = e.target;
            if (!target ||
                !target.tagName ||
                !Dom.isTag(target, 'input') ||
                target.type !== 'color') {
                return;
            }
            const color = target.value || '';
            if (isFunction(callback)) {
                callback(color);
            }
            e.preventDefault();
        });
    }
    editor.e.on(form, 'mousedown touchend', (e) => {
        // let the hex/native inputs receive focus and clicks
        if (Dom.isTag(e.target, 'input')) {
            e.stopPropagation();
            return;
        }
        e.stopPropagation();
        e.preventDefault();
        let target = e.target;
        if ((!target ||
            !target.tagName ||
            Dom.isTag(target, 'svg') ||
            Dom.isTag(target, 'path')) &&
            target.parentNode) {
            target = Dom.closest(target.parentNode, 'span', editor.editor);
        }
        if (!Dom.isTag(target, 'span') ||
            (!target.classList.contains(cn + '__color-item') &&
                !target.classList.contains(cn + '__remove'))) {
            return;
        }
        const color = attr(target, '-color') || '';
        if (callback && isFunction(callback)) {
            callback(color);
        }
    });
    editor.e.fire('afterGenerateColorPicker', form, extra, callback, valueHex);
    return form;
};
